@startuml

class WebPortal {
  + versionNumber : string
  + url : string
}

class Building {
  + id : string
  + name : string
  + address : string
  + yearOfConstruction : int
}

class Entry {
  + name : string
  + public : boolean
}

class TextEntry extends Entry {
  + text : string
}

class NumericEntry extends Entry {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class Comment {
  + text : string
}

class User {
  + username : string
  + email : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

enum EnergyClass {
  A
  B
  C
  D
}

WebPortal "1" -- "*" Building
Building "1" -- "*" Entry
Building "1" -- "*" Image
Building "1" -- "*" Comment
User "1" -- "*" Building : owner
User "1" -- "*" Comment : author
WebPortal "1" -- "*" User : registered to

@enduml

